#include <vector>
#include <cstddef>
#include <cmath>
#include <stdexcept>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    if (b.size() != N) {
        throw std::invalid_argument("b.size() must equal N");
    }

    x.assign(N, 0.0);
    if (N == 0) return;

    // Build a dense matrix from COO safely in parallel.
    // Repeated COO entries are summed using atomic updates.
    std::vector<double> dense(N * N, 0.0);

    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(A.size()); ++k) {
        const COOElement &e = A[static_cast<size_t>(k)];
        if (e.row >= N || e.column >= N) {
            continue; // Ignore out-of-range entries.
        }
        #pragma omp atomic update
        dense[e.row * N + e.column] += e.value;
    }

    // Copy b into working RHS.
    std::vector<double> rhs(b.begin(), b.end());

    const double eps = 1e-12;

    // Gaussian elimination with partial pivoting.
    for (size_t k = 0; k < N; ++k) {
        // Find pivot row sequentially for determinism and simplicity.
        size_t pivot = k;
        double maxAbs = std::fabs(dense[k * N + k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(dense[i * N + k]);
            if (v > maxAbs) {
                maxAbs = v;
                pivot = i;
            }
        }

        if (maxAbs < eps) {
            throw std::runtime_error("Matrix is singular or nearly singular");
        }

        // Swap rows if needed.
        if (pivot != k) {
            for (size_t j = 0; j < N; ++j) {
                double tmp = dense[k * N + j];
                dense[k * N + j] = dense[pivot * N + j];
                dense[pivot * N + j] = tmp;
            }
            double tmpb = rhs[k];
            rhs[k] = rhs[pivot];
            rhs[pivot] = tmpb;
        }

        const double pivotVal = dense[k * N + k];

        // Eliminate rows below pivot in parallel.
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k) + 1; ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            size_t i = static_cast<size_t>(ii);
            double factor = dense[i * N + k] / pivotVal;
            dense[i * N + k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                dense[i * N + j] -= factor * dense[k * N + j];
            }
            rhs[i] -= factor * rhs[k];
        }
    }

    // Back substitution.
    for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(N) - 1; ii >= 0; --ii) {
        size_t i = static_cast<size_t>(ii);
        double sum = rhs[i];

        double dot = 0.0;
        #pragma omp parallel for reduction(+:dot) schedule(static)
        for (std::ptrdiff_t jj = static_cast<std::ptrdiff_t>(i) + 1; jj < static_cast<std::ptrdiff_t>(N); ++jj) {
            size_t j = static_cast<size_t>(jj);
            dot += dense[i * N + j] * x[j];
        }

        sum -= dot;
        double diag = dense[i * N + i];
        if (std::fabs(diag) < eps) {
            throw std::runtime_error("Matrix is singular or nearly singular during back substitution");
        }
        x[i] = sum / diag;
    }
}
